//! The differential gate: this crate's box tree against WeasyPrint's.
//!
//! `tests/fixtures/cases.tsv` holds a small HTML document per case and
//! `tests/fixtures/layout.tsv` holds the box tree WeasyPrint produced for it,
//! one row per box in depth-first order with the child index as the path. Both
//! are generated by `research/tools/gen_weasyprint_layout.py`, so the oracle is
//! the reference's own output rather than a transcription of it.
//!
//! Every case is laid out here and compared box by box. A failure names the box
//! by its path and reports each measurement that differs, which is the point of
//! checking a tree rather than a rendered page.

use std::collections::BTreeMap;

use cssprint::{LayoutBox, Stylesheet, layout};

/// One expected box, as read from the fixture.
#[derive(Debug, Clone)]
struct Expected {
    tag: String,
    text: String,
    content_x: f64,
    content_y: f64,
    width: f64,
    height: f64,
    margin: [f64; 4],
    padding: [f64; 4],
    border: [f64; 4],
}

/// A measurement, for reporting which one differs.
struct Field {
    name: &'static str,
    actual: f64,
    expected: f64,
}

/// Two boxes agree when every measurement is within this much.
///
/// The reference computes in floats, and a percentage of a percentage can land
/// a hair apart. A tenth of a pixel is far below anything a printer resolves and
/// far above float noise.
const TOLERANCE: f64 = 0.1;

fn fixture(name: &str) -> String {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join(name);
    std::fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("cannot read {}: {error}", path.display()))
}

/// Read `cases.tsv` into `case -> html`.
fn cases() -> BTreeMap<String, String> {
    let mut map = BTreeMap::new();
    for line in fixture("cases.tsv").lines() {
        if line.starts_with('#') || line.trim().is_empty() {
            continue;
        }
        let (case, html) = line.split_once('\t').expect("case<TAB>html");
        // The generator escapes a tab and a newline so a case stays one row.
        map.insert(case.to_owned(), unescape(html));
    }
    map
}

/// Reverse the generator's escaping of a TSV field.
fn unescape(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut characters = text.chars();
    while let Some(character) = characters.next() {
        if character != '\\' {
            out.push(character);
            continue;
        }
        match characters.next() {
            Some('n') => out.push('\n'),
            Some('t') => out.push('\t'),
            Some('\\') => out.push('\\'),
            Some(other) => out.push(other),
            None => out.push('\\'),
        }
    }
    out
}

/// Read `layout.tsv` into `case -> path -> expected box`.
fn expected() -> BTreeMap<String, BTreeMap<String, Expected>> {
    let mut map: BTreeMap<String, BTreeMap<String, Expected>> = BTreeMap::new();
    for line in fixture("layout.tsv").lines() {
        if line.starts_with('#') || line.trim().is_empty() {
            continue;
        }
        let field: Vec<&str> = line.split('\t').collect();
        let number = |index: usize| -> f64 {
            let text = field.get(index).copied().unwrap_or("");
            if text.is_empty() {
                0.0
            } else {
                text.parse()
                    .unwrap_or_else(|_| panic!("cannot read number `{text}`"))
            }
        };
        let box_ = Expected {
            tag: field[2].to_owned(),
            text: field.get(20).copied().unwrap_or("").to_owned(),
            content_x: number(4),
            content_y: number(5),
            width: number(6),
            height: number(7),
            // The fixture writes the sides left, right, top, bottom; the
            // LayoutBox stores them top, right, bottom, left.
            margin: [number(10), number(9), number(11), number(8)],
            padding: [number(14), number(13), number(15), number(12)],
            border: [number(18), number(17), number(19), number(16)],
        };
        map.entry(field[0].to_owned())
            .or_default()
            .insert(field[1].to_owned(), box_);
    }
    map
}

/// Flatten a laid-out tree into `path -> box`, the same shape as the fixture.
fn flatten(root: &LayoutBox, path: &str, out: &mut BTreeMap<String, Expected>) {
    out.insert(
        if path.is_empty() { "0" } else { path }.to_owned(),
        Expected {
            tag: root.tag.clone(),
            text: root.text.clone().unwrap_or_default(),
            content_x: root.content_x,
            content_y: root.content_y,
            width: root.width,
            height: root.height,
            margin: [
                root.margin.top,
                root.margin.right,
                root.margin.bottom,
                root.margin.left,
            ],
            padding: [
                root.padding.top,
                root.padding.right,
                root.padding.bottom,
                root.padding.left,
            ],
            border: [
                root.border.top,
                root.border.right,
                root.border.bottom,
                root.border.left,
            ],
        },
    );
    for (index, child) in root.children.iter().enumerate() {
        let child_path = if path.is_empty() {
            index.to_string()
        } else {
            format!("{path}.{index}")
        };
        flatten(child, &child_path, out);
    }
}

/// Every case in the corpus, compared against the reference box by box.
#[test]
fn matches_weasyprint_box_tree() {
    let cases = cases();
    let expected = expected();
    assert!(!cases.is_empty(), "the corpus is empty");

    let mut failures = Vec::new();
    for (case, html) in &cases {
        // The corpus declares its own `@page` and stylesheet; the crate takes
        // the page width and the sheet separately, so the page size is read back
        // out of the HTML and the rest of the `<style>` becomes the sheet.
        let (page_width, stylesheet_text) = split_case(html);
        let sheet = Stylesheet::parse(&stylesheet_text)
            .unwrap_or_else(|error| panic!("{case}: stylesheet: {error}"));
        let document = layout(html, &sheet, page_width)
            .unwrap_or_else(|error| panic!("{case}: layout: {error}"));

        let mut actual = BTreeMap::new();
        flatten(&document.root, "", &mut actual);

        let Some(want) = expected.get(case) else {
            failures.push(format!("{case}: no expected tree in the fixture"));
            continue;
        };
        compare(case, want, &actual, &mut failures);
    }

    assert!(
        failures.is_empty(),
        "{} difference(s) from WeasyPrint:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

/// Compare one case's actual tree with the expected one.
fn compare(
    case: &str,
    want: &BTreeMap<String, Expected>,
    actual: &BTreeMap<String, Expected>,
    failures: &mut Vec<String>,
) {
    for (path, expected) in want {
        let Some(got) = actual.get(path) else {
            failures.push(format!("{case} [{path}]: the crate produced no such box"));
            continue;
        };
        if got.tag != expected.tag {
            failures.push(format!(
                "{case} [{path}]: tag is `{}`, expected `{}`",
                got.tag, expected.tag
            ));
        }
        if got.text != expected.text {
            failures.push(format!(
                "{case} [{path}]: text is {:?}, expected {:?}",
                got.text, expected.text
            ));
        }
        let fields = [
            Field {
                name: "content_x",
                actual: got.content_x,
                expected: expected.content_x,
            },
            Field {
                name: "content_y",
                actual: got.content_y,
                expected: expected.content_y,
            },
            Field {
                name: "width",
                actual: got.width,
                expected: expected.width,
            },
            Field {
                name: "height",
                actual: got.height,
                expected: expected.height,
            },
            Field {
                name: "margin.top",
                actual: got.margin[0],
                expected: expected.margin[0],
            },
            Field {
                name: "margin.right",
                actual: got.margin[1],
                expected: expected.margin[1],
            },
            Field {
                name: "margin.bottom",
                actual: got.margin[2],
                expected: expected.margin[2],
            },
            Field {
                name: "margin.left",
                actual: got.margin[3],
                expected: expected.margin[3],
            },
            Field {
                name: "padding.top",
                actual: got.padding[0],
                expected: expected.padding[0],
            },
            Field {
                name: "padding.right",
                actual: got.padding[1],
                expected: expected.padding[1],
            },
            Field {
                name: "padding.bottom",
                actual: got.padding[2],
                expected: expected.padding[2],
            },
            Field {
                name: "padding.left",
                actual: got.padding[3],
                expected: expected.padding[3],
            },
            Field {
                name: "border.top",
                actual: got.border[0],
                expected: expected.border[0],
            },
            Field {
                name: "border.right",
                actual: got.border[1],
                expected: expected.border[1],
            },
            Field {
                name: "border.bottom",
                actual: got.border[2],
                expected: expected.border[2],
            },
            Field {
                name: "border.left",
                actual: got.border[3],
                expected: expected.border[3],
            },
        ];
        for field in fields {
            if (field.actual - field.expected).abs() > TOLERANCE {
                failures.push(format!(
                    "{case} [{path}] <{}>: {} is {}, expected {}",
                    expected.tag, field.name, field.actual, field.expected
                ));
            }
        }
    }

    for path in actual.keys() {
        if !want.contains_key(path) {
            failures.push(format!("{case} [{path}]: the crate produced an extra box"));
        }
    }
}

/// Split a case into its page width and the stylesheet to apply.
///
/// Each case begins with `<style>@page { size: Wpx Hpx; margin: 0 } ...`, and
/// the `@page` rule is not something this crate parses, so it is removed here.
/// The rest of the `<style>` is the sheet.
fn split_case(html: &str) -> (f64, String) {
    let open = html.find("<style>").expect("a case has a <style> block") + "<style>".len();
    let close = html[open..]
        .find("</style>")
        .expect("a case closes its <style>")
        + open;
    let sheet = &html[open..close];

    let size = sheet.find("size:").expect("a case declares a page size") + "size:".len();
    let after = &sheet[size..];
    let end = after
        .find(';')
        .expect("the page size ends with a semicolon");
    let width = after[..end]
        .split_whitespace()
        .next()
        .expect("the page size has a width")
        .trim_end_matches("px")
        .parse()
        .expect("the page width is a number");

    let sheet = sheet.replace(
        &sheet[sheet.find("@page").expect("@page is present")
            ..=sheet.find('}').expect("@page is closed")],
        "",
    );
    (width, sheet)
}
